  Lemma dtv_not_written : forall s s' d lo SP mo1 mo' a,
    placed_ok s -> placed_ok s' -> a_thr s' = a_thr s -> a_sb s' = a_sb s -> a_pa s' = a_pa s -> aceil <= lo ->
    akobj (ip_D p) kPageSize -> ip_D p + 32 <= aceil -> 0 < ip_D p ->
    IDAPART p s d -> (forall sc, In sc (as_sec (a_st s)) -> disj (sc_map_beg sc) (sc_map_size sc) (ip_D p) kPageSize) ->
    dtv_cov p mo1 -> avmx s s' mo1 mo' ->
    ip_D p <= a < ip_D p + 32 -> ~ awrit s s' d lo SP a.
  Proof.
    intros s s' d lo SP mo1 mo' a PL PL' ET ESB EPA LO AKD DCE DPOS (DA1 & DA2 & DA3 & DA4 & DA5) DSEC DTV AVX HD W.
    pose proof PL as (_ & S2 & S3 & _ & P2 & P3 & _ & T2 & T3 & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & SEC & _).
    pose proof PL' as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & SEC' & _).
    assert (NL : ~ (ALOWSH_LO <= a < AHI_LO)).
    { intros L. clear - AKD DCE HD L. acb. unfold akobj, alow1, aapp, aapp_lo, aapp_hi, AIMG_LO, AIMG_TOP, ALOWSH_LO, AHI_LO, kPageSize in *. lia. }
    acb. unfold awrit in W. destruct W as [C|[C|[C|[C|[C|[C|[C|[C|C]]]]]]]].
    - lia.
    - clear - DA2 C HD. unfold disj, kPageSize in *. lia.
    - clear - DA1 C HD. unfold disj, kPageSize in *. lia.
    - apply NL. apply (sh_land (a_sb s) (kSpaceSize + kPageSize)); [unfold AHI_LO, AIMG_TOP in *; lia| clear - S3; lia|].
      clear - C. unfold sh, kSpaceSize, kPageSize in *. Z.div_mod_to_equations. lia.
    - clear - DA3 C HD. unfold disj, kPageSize in *. lia.
    - destruct C as (sc & IN & R).
      assert (Q : aapp (sc_map_beg sc) (sc_map_size sc) /\ sc_map_beg sc + sc_map_size sc <= aceil).
      { destruct IN as [IN|IN]; [pose proof (SEC sc IN) as (_ & A & B & _)| pose proof (SEC' sc IN) as (_ & A & B & _)]; exact (conj A B). }
      destruct Q as [AP CE]. destruct R as [R|R].
      + destruct (in_dec schunk_eq_dec sc (as_sec (a_st s))) as [INs|NIs].
        * pose proof (DSEC sc INs) as DS. clear - DS R HD. unfold disj, kPageSize in *. lia.
        * destruct IN as [IN|IN]; [exact (NIs IN)|].
          assert (RA : 0 <= a < 2 ^ 64) by lia.
          pose proof (DTV (wz a) ltac:(unfold wz; rewrite unsigned_lit by exact RA; unfold kPageSize; lia)) as CV.
          pose proof (proj2 (AVX (wz a) CV) sc IN NIs) as NR. apply NR. unfold wz. rewrite unsigned_lit by exact RA. exact R.
      + apply NL. apply (sh_land (sc_map_beg sc) (sc_map_size sc)); [exact (aapp_ge_top _ _ AP)| exact CE| exact R].
    - clear - AKD C HD. aunf. unfold astatw, AINST, AIAINIT, AIAINST, kPageSize in *. lia.
    - clear - DA4 C HD. unfold disj, kPageSize in *. lia.
    - clear - DA5 C HD. unfold disj, kPageSize in *. lia.
  Qed.


  (* [comment removed for export] *)
  Lemma zinb_In : forall x l, zinb x l = true <-> In x l.
  Proof.
    induction l as [|y l IH]; cbn; [split; [discriminate| tauto]|].
    destruct (Z.eqb_spec x y); [subst; tauto|]. rewrite IH. split; [tauto|]. intros [E|H]; [congruence| exact H].
  Qed.
  Lemma length_filter_negb : forall (A : Type) (f : A -> bool) (l : list A),
    (length (List.filter f l) + length (List.filter (fun x => negb (f x)) l) = length l)%nat.
  Proof. intros A f l. induction l as [|x l IH]; [reflexivity|]. cbn [List.filter]. destruct (f x); cbn [negb length Nat.add]; rewrite ?Nat.add_succ_r; congruence. Qed.
  Lemma NoDup_filter : forall (A : Type) (f : A -> bool) (l : list A), List.NoDup l -> List.NoDup (List.filter f l).
  Proof.
    intros A f l ND. induction l as [|x l IH]; cbn; [constructor|]. inversion ND; subst.
    destruct (f x); [| apply IH; assumption]. constructor; [| apply IH; assumption]. intros K. apply filter_In in K as [K _]. contradiction.
  Qed.
  Lemma d_K_len : forall d, 0 <= d_ids d -> length (d_K d) = Z.to_nat (d_ids d).
  Proof. intros d H. unfold d_K, idseq. rewrite !length_map, length_seq. reflexivity. Qed.


  Lemma nwild_put : forall d h n, 0 <= d_ids d -> 1 <= d_ids d ->
    nwild p (d_put d h n) = nwild p d + (if (d_find d h =? 0) && wildh p h then 1 else 0)%bool.
  Proof.
    intros d h n H0 H1. unfold nwild, d_put. destruct (Z.eqb_spec (d_find d h) 0) as [Z0|NZ]; cbn [andb]; [| lia].
    rewrite (d_K_insert d h n ltac:(lia)).
    pose proof (d_K_len d ltac:(lia)) as LK. destruct (d_K d) as [|h1 tlK] eqn:EK; [cbn in LK; lia|].
    cbn [tl app]. rewrite filter_app, length_app, Nat2Z.inj_add. cbn [List.filter]. destruct (wildh p h); cbn [length Z.of_nat Pos.of_succ_nat]; lia.
  Qed.

  Lemma depot_trw_put : forall d h n, d_wf d -> depot_trw p d -> 0 <= n <= 31 ->
    (wildh p h = true -> d_find d h = 0 -> nwild p d + 1 <= AWMAX) ->
    depot_trw p (d_put d h n).
  Proof.
    intros d h n W (T1 & T3 & T4 & T5) Hn ROOM.
    pose proof (nwild_put d h n ltac:(lia) T1) as NW.
    unfold d_put in *. destruct (Z.eqb_spec (d_find d h) 0) as [Z0|NZ]; [| exact (conj T1 (conj T3 (conj T4 T5)))].
    assert (NI : ~ In h (d_K d)) by (intros K; apply (proj2 (d_find_K d h W)) in K; exact (K Z0)).
    split; [cbn [d_ids d_insert]; lia|]. split.
    - rewrite (d_K_insert d h n ltac:(lia)). apply NoDup_app; [exact T3| constructor; [intros []| constructor]|].
      intros a Ha [<-|[]]. exact (NI Ha).
    - split; [cbn [d_ids d_frames d_insert]; lia|]. rewrite NW. cbn [andb]. destruct (wildh p h) eqn:WH; [| lia].
      specialize (ROOM eq_refl Z0). lia.
  Qed.
  Lemma depot_trw_put_known : forall d h n, d_wf d -> depot_trw p d -> In h (map depot_hash (ip_TR p)) -> 0 <= n <= 31 ->
    depot_trw p (d_put d h n) /\ nwild p (d_put d h n) = nwild p d.
  Proof.
    intros d h n W T Hh Hn.
    assert (WH : wildh p h = false) by (unfold wildh; apply negb_false_iff; apply zinb_In; exact Hh).
    split; [apply (depot_trw_put d h n W T Hn); intros K; rewrite WH in K; discriminate K|].
    rewrite (nwild_put d h n ltac:(destruct T; lia) (proj1 T)), WH, andb_false_r. lia.
  Qed.
  Lemma depot_trw_put_wild : forall d h n, d_wf d -> depot_trw p d -> nwild p d + 1 <= AWMAX -> 0 <= n <= 31 ->
    depot_trw p (d_put d h n) /\ nwild p (d_put d h n) <= nwild p d + 1.
  Proof.
    intros d h n W T ROOM Hn. split; [apply (depot_trw_put d h n W T Hn); intros _ _; exact ROOM|].
    rewrite (nwild_put d h n ltac:(destruct T; lia) (proj1 T)). destruct ((d_find d h =? 0) && wildh p h)%bool; lia.
  Qed.
  Lemma depot_trw_of_tr : forall d, depot_tr p d -> depot_trw p d /\ nwild p d = 0.
  Proof.
    intros d (T1 & T2 & T3 & T4).
    assert (NW : nwild p d = 0).
    { unfold nwild. pose proof (d_K_len d ltac:(lia)) as LK.
      assert (ALL : forall h, In h (tl (d_K d)) -> wildh p h = false).
      { intros h Hh. unfold wildh. apply negb_false_iff. apply zinb_In. unfold TRH.
        unfold d_K, idseq in Hh. destruct (Z.to_nat (d_ids d)) as [|k] eqn:EK; [cbn in Hh; destruct Hh|].
        rewrite <- cons_seq in Hh. cbn [map tl] in Hh. apply in_map_iff in Hh. destruct Hh as (idn & <- & Hid).
        apply in_map_iff in Hid. destruct Hid as (j & <- & Hj). apply in_seq in Hj. apply T2. lia. }
      replace (List.filter (wildh p) (tl (d_K d))) with (@nil Z); [reflexivity|]. symmetry.
      induction (tl (d_K d)) as [|x l IH]; [reflexivity|]. cbn. rewrite (ALL x (or_introl eq_refl)). apply IH. intros h Hh. apply ALL. right. exact Hh. }
    split; [| exact NW]. split; [exact T1|]. split; [exact T3|]. split; [exact T4|]. rewrite NW. unfold AWMAX. lia.
  Qed.

  Hypothesis TRLEN : (length (ip_TR p) <= 256)%nat.   (* [comment removed for export] *)   (* [comment removed for export] *)

  Lemma dcap_of_trw : forall d, depot_trw p d -> d_ids d + 1 < 65536 /\ d_frames d + 31 <= 262144.
  Proof.
    intros d (T1 & T3 & T4 & T5).
    assert (IDS : d_ids d <= 8057); [| lia].   (* [comment removed for export] *)
    pose proof (d_K_len d ltac:(lia)) as LK.
    destruct (d_K d) as [|h1 tlK] eqn:EK; [cbn in LK; lia|]. cbn [length] in LK.
    assert (ND2 : List.NoDup tlK) by (apply NoDup_cons_iff in T3; exact (proj2 T3)).
    unfold nwild in T5. rewrite EK in T5. cbn [tl] in T5.
    pose proof (length_filter_negb Z (fun h => zinb h (TRH p)) tlK) as LEN. cbv beta in LEN. unfold wildh in T5.
    assert (INC : incl (List.filter (fun h => zinb h (TRH p)) tlK) (TRH p)).
    { intros h Hh. apply filter_In in Hh as [_ Hh]. apply zinb_In. exact Hh. }
    pose proof (NoDup_incl_length (NoDup_filter Z _ tlK ND2) INC) as L.
    assert (LT : length (TRH p) = length (ip_TR p)) by (unfold TRH; apply length_map). rewrite LT in L.
    set (a := length (List.filter (fun h : Z => zinb h (TRH p)) tlK)) in *. set (b := length (List.filter (fun h : Z => negb (zinb h (TRH p))) tlK)) in *.
    unfold AWMAX in T5.
    assert (E : Z.of_nat (S (length tlK)) = d_ids d) by (rewrite LK; apply Z2Nat.id; clear - T1; lia).
    rewrite Nat2Z.inj_succ in E. apply (f_equal Z.of_nat) in LEN. rewrite Nat2Z.inj_add in LEN.
    apply Nat2Z.inj_le in L. pose proof (proj1 (Nat2Z.inj_le _ _) TRLEN) as TRZ.
    clear - E LEN L T5 TRZ. lia.
  Qed.
